INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.135.0',
  '2026-11-21',
  'Diary — копирование записи в буфер',
  E'Diary. У каждой записи появилась кнопка 📋 — копирует её текст в буфер обмена. Если запись длинная и в списке показана укороченной, скопируется всё равно целиком, а не до обрыва. Кнопка на секунду превращается в ✅, чтобы в списке было видно, какую именно запись вы скопировали.\n\nКопируется только текст: дата и время и так видны в списке, а в буфере они бы мешали вставлять запись в переписку или заметку.',
  E'Кнопка 📋 в шапке записи Diary (DiaryView.vue), рядом с ✏️ и 🗑. Запись выводится в div, а не в поле ввода, поэтому глобальная кнопка копирования из shared/copyField.ts на неё не распространяется.\n\nДобавлен writeClipboardText(text) в shared/clipboard.ts (рядом с readClipboardText): Clipboard API, а при отказе — фолбэк через скрытую textarea + execCommand(''copy''). Фолбэк нужен в вебвью без secure context, и для произвольного текста (а не значения поля, как в copyField.ts) иначе не обойтись: execCommand копирует только выделение в реальном элементе документа. setSelectionRange после select() — iOS игнорирует select() у readonly-поля. Возвращает false («скопировать не вышло»), тост показывает вызывающий.\n\nПодсветка ✅ живёт в copiedId + таймер 1.5 с: тоста мало, когда записей в списке несколько. Версия страницы /diary выставлена впервые (раньше meta.version у неё не было) — 2.135.'
);
